draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw a plate with food
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 100, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 100, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 100, 5, 0, 2 * Math.PI);
  ctx.fill();

  // animate the character eating
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 100 - 30 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
